     9	
    10	const logger = createLogger("mcp-app-result-snapshots");
    11	
    12	const MCP_APP_RESULT_MAX_BYTES = 512 * 1024;
    13	const MCP_APP_RESULT_RETENTION_DAYS = 30;
    14	const MCP_APP_RESULT_CONVERSATION_CAP = 50;
    15	const TOOL_CALL_ID_MAX_LENGTH = 512;
    16	const TOOL_NAME_MAX_LENGTH = 120;
    17	const VIEW_STATE_MAX_KEYS = 100;
    18	const VIEW_STATE_KEY_MAX_LENGTH = 120;
    19	const VIEW_STATE_STRING_MAX_LENGTH = 500;
    20	const VIEW_STATE_MAX_BYTES = 8 * 1024;
    21	
    22	type UnknownRecord = Record<string, unknown>;
    23	type McpAppViewState = Record<string, boolean | number | string>;
    24	
    25	interface SnapshotPayload {
    26		version: 1;
    27		toolName: string;
    28		data: UnknownRecord;
    29		viewState: McpAppViewState;
    30		/** SHA-256 of the single-use capability; retained after binding for idempotency. */
    31		bindingKey?: string;
    32	}
    33	
    34	interface SnapshotIdentity {
    35		organizationId: string;
    36		clientId: string;
    37		userId: string;
    38		conversationKey: string;
    39		toolCallKey: string;
    40	}
    41	
    42	interface SnapshotRow {
    43		body: string;
    44		tool_name: string;
    45	}
    46	
    47	interface SnapshotLookupRow extends SnapshotRow {
    48		tool_call_key: string;
    49	}
    50	
    51	function isRecord(value: unknown): value is UnknownRecord {
    52		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
    53	}
    54	
    55	export function normalizeMcpAppToolCallId(value: unknown): string | null {
    56		if (typeof value !== "string" && typeof value !== "number") return null;
    57		if (typeof value === "number" && !Number.isFinite(value)) return null;
    58		const normalized = String(value).trim();
    59		return normalized && normalized.length <= TOOL_CALL_ID_MAX_LENGTH
    60			? normalized
    61			: null;
    62	}
    63	
    64	function hashIdentity(value: string): string {
    65		return createHash("sha256").update(value, "utf8").digest("hex");
    66	}
    67	
    68	function snapshotIdentity(
    69		ctx: ToolContext,
    70		toolCallId: unknown,
    71	): SnapshotIdentity | null {
    72		const normalizedToolCallId = normalizeMcpAppToolCallId(toolCallId);
    73		const conversationId = ctx.mcpConversationId?.trim();
    74		if (
    75			ctx.mcpAppsSupported !== true ||
    76			ctx.tokenType !== "oauth" ||
    77			!ctx.clientId ||
    78			!ctx.userId ||
    79			!conversationId ||
    80			conversationId.length > 512 ||
    81			!normalizedToolCallId
    82		) {
    83			return null;
    84		}
    85		return {
    86			organizationId: ctx.organizationId,
    87			clientId: ctx.clientId,
    88			userId: ctx.userId,
    89			conversationKey: hashIdentity(conversationId),
    90			toolCallKey: hashIdentity(normalizedToolCallId),
    91		};
    92	}
    93	
    94	/** Remove live approval mutations before a historical result is persisted. */
    95	export function displaySafeMcpAppResult(value: unknown): unknown {
    96		if (Array.isArray(value)) return value.map(displaySafeMcpAppResult);
    97		if (!isRecord(value)) return value;
    98		return Object.fromEntries(
    99			Object.entries(value).map(([key, inner]) => {
   100				if (key === "actions" && Array.isArray(inner)) {
   101					return [
