import { act, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

type CompatParent = EventTarget & { location: { origin: string } };
const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

function restore(
	name: "parent" | "openai",
	descriptor: PropertyDescriptor | undefined,
) {
	if (descriptor) Object.defineProperty(window, name, descriptor);
	else Reflect.deleteProperty(window, name);
}

describe("review reproducer", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
		bridge.callServerTool.mockImplementation(
			async ({ name, arguments: args }) => {
				if (
					name === "restore_lobu_app_result" &&
					args.snapshot_capability === "first-cap"
				) {
					return {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "query_sdk",
							data: { title: "First" },
							view_state: { "table.page": 1 },
						},
					};
				}
				if (name === "save_lobu_app_state") {
					return { isError: false, structuredContent: { saved: true } };
				}
				return {
					isError: false,
					structuredContent: { found: false, view_state: {} },
				};
			},
		);
	});

	afterEach(() => {
		restore("parent", originalParentDescriptor);
		restore("openai", originalOpenAiDescriptor);
	});

	it("does not carry prior state into a later metadata-less result", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, setViewState, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<span>page:{String(viewState["table.page"])}</span>
					<button type="button" onClick={() => setViewState("table.page", 9)}>
						Edit
					</button>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "dev" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolOutput: { title: "First" },
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/mcp-app-snapshot-capability": "first-cap",
									},
								},
							},
						},
					},
				}),
			),
		);
		expect(await screen.findByText("page:1")).toBeInTheDocument();
		fireEvent.click(screen.getByRole("button", { name: "Edit" }));
		expect(screen.getByText("page:9")).toBeInTheDocument();
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: { globals: { toolOutput: { title: "Second" } } },
				}),
			),
		);
		expect(await screen.findByText("Second")).toBeInTheDocument();
		expect(screen.getByText("page:undefined")).toBeInTheDocument();
	});
});

